describe('Mobile User Experience', () => {
  it('should display the inventory page on mobile', () => {
    cy.visit('https://www.saucedemo.com');
    cy.get('input[name="user_name"]').type('standard_user');
    cy.get('input[name="password"]').type('secret_sauce');
    cy.get('input[name="user_name"]').should('be.visible');
    cy.get('input[name="password"]').should('be.visible');
    cy.get('input[name="user_name"]').should('have.attr', 'value', 'standard_user');
    cy.get('input[name="password"]').should('have.attr', 'value', 'secret_sauce');
    cy.get('input[name="user_name"]').click();
    cy.get('input[name="password"]').click();
    cy.url().should('include', '/inventory');
  });

  it('should not change the URL when clicking the burger menu button on mobile', () => {
    cy.visit('https://www.saucedemo.com');
    cy.get('#react-burger-menu-btn').click();
    cy.url().should('include', '/inventory');
  });
});
